var Clay = require('@rebble/clay');
var clayConfig = require('./config.json');
var keys = require('message_keys');

// Build environment (generated by wscript from REVOLVER_ENV; prod by default)
var env = require('./env');

// Rebuilt on every settings open: the login link carries a fresh pairing code.
var AUTH_LINK_PLACEHOLDER = '{{AUTH_URL}}';
var CLAY_TEMPLATE = JSON.stringify(clayConfig);

function buildClay(authUrl) {
  var config = JSON.parse(CLAY_TEMPLATE);
  config.forEach(function (section) {
    (section.items || []).forEach(function (item) {
      if (
        typeof item.defaultValue === 'string' &&
        item.defaultValue.indexOf(AUTH_LINK_PLACEHOLDER) !== -1
      ) {
        item.defaultValue = item.defaultValue.replace(AUTH_LINK_PLACEHOLDER, authUrl);
      }
    });
  });
  return new Clay(config, null, { autoHandleEvents: false });
}

var clay = buildClay(env.AUTH_URL);

// Auth Proxy
var LAMBDA_URL = env.LAMBDA_URL;

// Connected Vehicle API
var VOLVO_API = 'https://api.volvocars.com/connected-vehicle/v2';

// Energy API v2 (battery state for EVs/PHEVs; requires energy:state:read scope)
var ENERGY_API = 'https://api.volvocars.com/energy/v2';

// Location API v1 (parked car position; requires location:read scope)
var LOCATION_API = 'https://api.volvocars.com/location/v1';

// Command registry (must match C COMMANDS[] bit flags)
var COMMANDS = {
  flash: { bit: 0x01, success: 'Flashed!' },
  honk: { bit: 0x02, success: 'Honked!' },
  'honk-flash': { bit: 0x04, success: 'Honked!' },
  lock: { bit: 0x08, success: 'Locked!' },
  unlock: { bit: 0x10, success: 'Unlocked!' },
  'climatization-start': { bit: 0x20, success: 'Climate on!' },
  'climatization-stop': { bit: 0x40, success: 'Climate off!' },
  'engine-start': {
    bit: 0x80,
    success: 'Started!',
    body: function (p) {
      return JSON.stringify({ runtimeMinutes: parseInt(p, 10) });
    }
  },
  'engine-stop': { bit: 0x100, success: 'Stopped!' }
};

var STORE = {
  VIN: 'revolver_vin',
  ACCESS_TOKEN: 'revolver_access_token',
  REFRESH_TOKEN: 'revolver_refresh_token',
  EXPIRES_AT: 'revolver_expires_at',
  VCC_API_KEY: 'revolver_vcc_api_key',
  CAR_INFO: 'revolver_car_info',
  AVAILABLE_COMMANDS: 'revolver_commands',
  ENERGY_CAPABLE: 'revolver_energy_capable',
  PAIRING: 'revolver_pairing'
};

// Storage

function get(key) {
  return localStorage.getItem(key) || '';
}

function set(key, val) {
  localStorage.setItem(key, val);
}

function clear(key) {
  localStorage.removeItem(key);
}

// HTTP Helper

// Unwraps a Volvo response (which may or may not nest under `data`) and
// returns the named field, or undefined.
function field(resp, name) {
  var payload = resp && (resp.data || resp);
  return payload && payload[name];
}

function volvoGet(path, cb) {
  var url = path.indexOf('http') === 0 ? path : VOLVO_API + path;
  var req = new XMLHttpRequest();
  req.open('GET', url);
  req.setRequestHeader('Authorization', 'Bearer ' + get(STORE.ACCESS_TOKEN));
  req.setRequestHeader('vcc-api-key', get(STORE.VCC_API_KEY));
  req.setRequestHeader('Accept', 'application/json');
  req.onload = function () {
    if (req.status === 200) {
      try {
        cb(JSON.parse(req.responseText));
      } catch (e) {
        cb(null, req.status);
      }
    } else {
      cb(null, req.status);
    }
  };
  req.onerror = function () {
    cb(null, 0);
  };
  req.send();
}

// Token Refresh

var refreshInFlight = false;
var refreshQueue = [];

function tokenExpired() {
  var token = get(STORE.ACCESS_TOKEN);
  if (!token) return false;
  if (!get(STORE.VCC_API_KEY)) return true;

  var expiresAt = parseInt(get(STORE.EXPIRES_AT), 10);
  if (!expiresAt) return true;

  return expiresAt - Math.floor(Date.now() / 1000) < 60;
}

function refreshToken(cb) {
  if (refreshInFlight) {
    if (cb) refreshQueue.push(cb);
    return;
  }

  var token = get(STORE.REFRESH_TOKEN);
  if (!token) {
    if (cb) cb(false);
    return;
  }

  refreshInFlight = true;
  if (cb) refreshQueue.push(cb);
  console.log('Refreshing with RT: ' + token.substring(0, 8) + '...');

  var req = new XMLHttpRequest();
  req.open('POST', LAMBDA_URL);
  req.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
  req.onload = function () {
    refreshInFlight = false;
    var callbacks = refreshQueue;
    refreshQueue = [];

    if (req.status === 200) {
      var data = JSON.parse(req.responseText);
      set(STORE.ACCESS_TOKEN, data.access_token);
      if (data.refresh_token) {
        set(STORE.REFRESH_TOKEN, data.refresh_token);
      } else {
        console.log('WARNING: No refresh_token in response!');
      }
      if (data.expires_in)
        set(STORE.EXPIRES_AT, String(Math.floor(Date.now() / 1000) + data.expires_in));
      if (data.vcc_api_key) set(STORE.VCC_API_KEY, data.vcc_api_key);
      console.log(
        'Token refreshed. RT: ' +
          (data.refresh_token ? data.refresh_token.substring(0, 8) + '...' : 'NONE')
      );
      callbacks.forEach(function (callback) {
        callback(true);
      });
    } else {
      console.log('Refresh failed: ' + req.status + ' ' + req.responseText);
      if (req.status === 400 || req.status === 401) {
        clear(STORE.ACCESS_TOKEN);
        clear(STORE.REFRESH_TOKEN);
        clear(STORE.EXPIRES_AT);
      }
      callbacks.forEach(function (callback) {
        callback(false);
      });
    }
  };
  req.onerror = function () {
    refreshInFlight = false;
    var callbacks = refreshQueue;
    refreshQueue = [];
    console.log('Refresh network error');
    callbacks.forEach(function (callback) {
      callback(false);
    });
  };
  req.send('grant_type=refresh_token&refresh_token=' + encodeURIComponent(token));
}

// Browser Login Pairing
// The code goes to the browser in the auth page URL; the secret never leaves here.

var PAIR_POLL_MS = 3000;
var pairTimer = null;
var pairPollInFlight = false;

function lambdaPost(body, cb) {
  var req = new XMLHttpRequest();
  req.open('POST', LAMBDA_URL);
  req.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
  req.timeout = 15000; // Lambda cold start takes ~6 s
  req.onload = function () {
    var data = null;
    try {
      data = JSON.parse(req.responseText);
    } catch (e) {}
    cb(req.status, data);
  };
  req.onerror = req.ontimeout = function () {
    cb(0, null);
  };
  req.send(body);
}

function storedPairing() {
  var p = null;
  try {
    p = JSON.parse(get(STORE.PAIRING) || 'null');
  } catch (e) {}
  if (!p || !p.code || !p.secret || !(p.expiresAt > Date.now())) {
    clear(STORE.PAIRING);
    return null;
  }
  return p;
}

function stopPairing() {
  if (pairTimer) clearTimeout(pairTimer);
  pairTimer = null;
  clear(STORE.PAIRING);
}

function startPairing(cb) {
  lambdaPost('action=pair_start', function (status, data) {
    if (status !== 200 || !data || !data.code || !data.secret) {
      console.log('pair_start failed: ' + status);
      cb(null);
      return;
    }
    var p = {
      code: data.code,
      secret: data.secret,
      expiresAt: Date.now() + (data.expires_in || 600) * 1000
    };
    set(STORE.PAIRING, JSON.stringify(p));
    cb(p);
  });
}

function pollPairing() {
  if (pairTimer) clearTimeout(pairTimer);
  pairTimer = null;
  if (pairPollInFlight) return;
  var p = storedPairing();
  if (!p) return;

  pairPollInFlight = true;
  lambdaPost(
    'action=pair_poll&code=' +
      encodeURIComponent(p.code) +
      '&secret=' +
      encodeURIComponent(p.secret),
    function (status, data) {
      pairPollInFlight = false;
      var current = storedPairing();
      if (!current || current.code !== p.code) {
        // Replaced by a newer pairing (or stopped) while this poll was in flight
        if (current) pollPairing();
        return;
      }
      if (status === 200 && data && data.access_token) {
        console.log('Pairing: tokens received');
        saveAuth({
          ACCESS_TOKEN: data.access_token,
          REFRESH_TOKEN: data.refresh_token,
          EXPIRES_IN: data.expires_in,
          VCC_API_KEY: data.vcc_api_key
        });
        send({ COMMAND_RESULT: '+Logged in!' });
        return;
      }
      if (status === 404) {
        console.log('Pairing expired');
        stopPairing();
        return;
      }
      // 202 pending, or a network error: keep polling until the pairing expires
      pairTimer = setTimeout(pollPairing, PAIR_POLL_MS);
    }
  );
}

function saveAuth(data) {
  stopPairing();
  console.log('Auth payload keys: ' + Object.keys(data).join(', '));
  console.log(
    'VCC_API_KEY present: ' +
      (data.VCC_API_KEY ? 'yes (' + data.VCC_API_KEY.substring(0, 8) + '...)' : 'NO')
  );
  set(STORE.ACCESS_TOKEN, data.ACCESS_TOKEN);
  if (data.REFRESH_TOKEN) set(STORE.REFRESH_TOKEN, data.REFRESH_TOKEN);
  if (data.EXPIRES_IN)
    set(STORE.EXPIRES_AT, String(Math.floor(Date.now() / 1000) + parseInt(data.EXPIRES_IN, 10)));
  if (data.VCC_API_KEY) set(STORE.VCC_API_KEY, data.VCC_API_KEY);
  sendStatus();
}

// Message Queue

var msgQueue = [];
var msgSending = false;

function send(msg) {
  msgQueue.push(msg);
  pump();
}

function pump() {
  if (msgSending || msgQueue.length === 0) return;
  msgSending = true;
  var msg = msgQueue.shift();

  Pebble.sendAppMessage(
    msg,
    function () {
      msgSending = false;
      pump();
    },
    function () {
      msgSending = false;
      msgQueue.unshift(msg);
      setTimeout(pump, 200);
    }
  );
}

function sendStatus() {
  var vin = get(STORE.VIN);
  var token = get(STORE.ACCESS_TOKEN);

  var status = 'Open settings';
  if (vin && token) status = 'Ready';
  else if (token) status = 'Set VIN';
  else if (vin) status = 'Login needed';

  send({ VIN: vin || 'Not set', STATUS_MSG: status });

  // Send cached data
  var info = get(STORE.CAR_INFO);
  if (info) send({ CAR_INFO: info });

  var cachedCmds = get(STORE.AVAILABLE_COMMANDS);
  if (cachedCmds) {
    try {
      var mask = 0;
      JSON.parse(cachedCmds).forEach(function (cmd) {
        if (cmd in COMMANDS) mask |= COMMANDS[cmd].bit;
      });
      send({ AVAILABLE_CMDS: mask });
    } catch (e) {}
  }

  // Fetch live data if authenticated
  if (vin && token && get(STORE.VCC_API_KEY)) {
    fetchCommandAccessibility();
    if (!cachedCmds) fetchAvailableCommands();
    if (!info) fetchVehicleDetails();
    fetchCarStatus();
  }
}

function sendResult(text, ok) {
  send({ COMMAND_RESULT: (ok ? '+' : '-') + text });
}

// Data Fetchers

function fetchVehicleDetails() {
  var vin = get(STORE.VIN);
  volvoGet('/vehicles/' + vin, function (resp) {
    if (!resp) return;
    var data = resp.data || resp;
    var parts = [];
    if (data.descriptions && data.descriptions.model) parts.push(data.descriptions.model);
    if (data.modelYear) parts.push(String(data.modelYear));
    if (parts.length) {
      var str = parts.join(' ');
      set(STORE.CAR_INFO, str);
      send({ CAR_INFO: str });
    }
  });
}

function fetchAvailableCommands() {
  var vin = get(STORE.VIN);
  volvoGet('/vehicles/' + vin + '/commands', function (resp) {
    if (!resp) return;
    var cmds = (resp.data || []).map(function (c) {
      return c.command.toLowerCase().replace(/_/g, '-').replace('and-', '');
    });
    set(STORE.AVAILABLE_COMMANDS, JSON.stringify(cmds));
    console.log('Available commands: ' + cmds.join(', '));

    var mask = 0;
    cmds.forEach(function (cmd) {
      if (cmd in COMMANDS) mask |= COMMANDS[cmd].bit;
    });
    send({ AVAILABLE_CMDS: mask });
  });
}

function fetchCommandAccessibility() {
  var vin = get(STORE.VIN);
  volvoGet('/vehicles/' + vin + '/command-accessibility', function (resp) {
    if (!resp) {
      send({ STATUS_MSG: 'Ready' });
      return;
    }
    var status = field(resp, 'availabilityStatus');
    if (status && status.value) {
      console.log('Command accessibility: ' + status.value);
      var msg = status.value === 'UNAVAILABLE' ? 'Driving' : 'Ready';
      send({ STATUS_MSG: msg });
    } else {
      send({ STATUS_MSG: 'Ready' });
    }
  });
}

function fetchEnergyCapability(cb) {
  var cached = get(STORE.ENERGY_CAPABLE);
  if (cached === '1' || cached === '0') {
    cb(cached === '1');
    return;
  }
  // Not yet known for this VIN — check once and cache (capabilities are static per vehicle)
  var vin = get(STORE.VIN);
  volvoGet(ENERGY_API + '/vehicles/' + vin + '/capabilities', function (resp) {
    if (!resp) {
      // Couldn't determine (network/endpoint error) — don't cache, retry next launch
      cb(false);
      return;
    }
    var payload = resp.data || resp;
    var energyState = payload.getEnergyState;
    var capable = !!(energyState && energyState.isSupported === true);
    set(STORE.ENERGY_CAPABLE, capable ? '1' : '0');
    console.log('Energy state capable: ' + capable);
    cb(capable);
  });
}

function fetchCarStatus() {
  // Resolve energy capability once per VIN, then fetch live status.
  fetchEnergyCapability(doFetchCarStatus);
}

function doFetchCarStatus(energyCapable) {
  var vin = get(STORE.VIN);
  var data = {
    lock: '?',
    engine: '?',
    windows: '?',
    fuel: null,
    fuelRange: null,
    fuelRangeUnit: null,
    battery: null,
    electricRange: null,
    electricRangeUnit: null
  };
  var pending = energyCapable ? 6 : 5;

  function distUnit(unit) {
    return String(unit || '')
      .toLowerCase()
      .indexOf('mi') === 0
      ? 'mi'
      : 'km';
  }

  function finish() {
    if (--pending > 0) return;

    // Decide energy display: liquid fuel takes priority; battery for EVs.
    var type, value, range;
    if (data.fuel !== null) {
      type = 'F';
      value = Math.round(data.fuel) + 'L';
      range =
        data.fuelRange !== null ? Math.round(data.fuelRange) + distUnit(data.fuelRangeUnit) : '?';
    } else if (data.battery !== null) {
      type = 'B';
      value = Math.round(data.battery) + '%';
      range =
        data.electricRange !== null
          ? Math.round(data.electricRange) + distUnit(data.electricRangeUnit)
          : '?';
    } else {
      type = 'F';
      value = '?';
      range = '?';
    }

    // Format: "lock|engine|value|range|windows|type" (type: F=fuel, B=battery)
    var str =
      data.lock + '|' + data.engine + '|' + value + '|' + range + '|' + data.windows + '|' + type;
    send({ CAR_STATUS: str });
  }

  volvoGet('/vehicles/' + vin + '/doors', function (resp) {
    // Central lock can report LOCKED while an individual door/tailgate is
    // still UNLOCKED. Treat the car as Unlocked if any lockable field is.
    var lockFields = [
      'centralLock',
      'tailgate',
      'frontLeftDoor',
      'frontRightDoor',
      'rearLeftDoor',
      'rearRightDoor',
      'hood',
      'tankLid'
    ];
    var sawValue = false,
      anyUnlocked = false;
    for (var i = 0; i < lockFields.length; i++) {
      var lockField = field(resp, lockFields[i]);
      if (lockField && lockField.value) {
        sawValue = true;
        if (lockField.value === 'UNLOCKED') anyUnlocked = true;
      }
    }
    if (sawValue) {
      data.lock = anyUnlocked ? 'Unlocked' : 'Locked';
    }
    finish();
  });

  volvoGet('/vehicles/' + vin + '/engine-status', function (resp) {
    var engineStatus = field(resp, 'engineStatus');
    if (engineStatus && engineStatus.value) {
      data.engine = engineStatus.value === 'RUNNING' ? 'Running' : 'Off';
    }
    finish();
  });

  volvoGet('/vehicles/' + vin + '/fuel', function (resp) {
    var fuel = field(resp, 'fuelAmount');
    if (fuel && fuel.value !== undefined && fuel.value !== null) {
      var amount = parseFloat(fuel.value);
      if (!isNaN(amount)) data.fuel = amount;
    }
    finish();
  });

  volvoGet('/vehicles/' + vin + '/statistics', function (resp) {
    var distanceToEmpty = field(resp, 'distanceToEmpty');
    if (distanceToEmpty && distanceToEmpty.value !== undefined && distanceToEmpty.value !== null) {
      var range = parseFloat(distanceToEmpty.value);
      if (!isNaN(range)) {
        data.fuelRange = range;
        data.fuelRangeUnit = distanceToEmpty.unit;
      }
    }
    finish();
  });

  // Energy API v2 — battery charge + electric range (full EV / PHEV)
  if (energyCapable)
    volvoGet(ENERGY_API + '/vehicles/' + vin + '/state', function (resp) {
      var batteryLevel = field(resp, 'batteryChargeLevel');
      if (
        batteryLevel &&
        batteryLevel.status === 'OK' &&
        batteryLevel.value !== undefined &&
        batteryLevel.value !== null
      ) {
        var battery = parseFloat(batteryLevel.value);
        if (!isNaN(battery)) data.battery = battery;
      }
      var electricRange = field(resp, 'electricRange');
      if (
        electricRange &&
        electricRange.status === 'OK' &&
        electricRange.value !== undefined &&
        electricRange.value !== null
      ) {
        var electric = parseFloat(electricRange.value);
        if (!isNaN(electric)) {
          data.electricRange = electric;
          data.electricRangeUnit = electricRange.unit;
        }
      }
      finish();
    });

  volvoGet('/vehicles/' + vin + '/windows', function (resp) {
    var payload = resp && (resp.data || resp);
    if (payload) {
      var openWindows = [];
      if (payload.frontLeftWindow && payload.frontLeftWindow.value === 'OPEN')
        openWindows.push('FL');
      if (payload.frontRightWindow && payload.frontRightWindow.value === 'OPEN')
        openWindows.push('FR');
      if (payload.rearLeftWindow && payload.rearLeftWindow.value === 'OPEN') openWindows.push('BL');
      if (payload.rearRightWindow && payload.rearRightWindow.value === 'OPEN')
        openWindows.push('BR');
      if (payload.sunroof && payload.sunroof.value === 'OPEN') openWindows.push('RT');
      data.windows = openWindows.length > 0 ? openWindows.join(' ') : 'OK';
    }
    finish();
  });
}

// Command Execution

function isCommandAvailable(command) {
  var stored = get(STORE.AVAILABLE_COMMANDS);
  if (!stored) return true;
  try {
    var cmds = JSON.parse(stored);
    var check = command.indexOf(':') !== -1 ? command.split(':')[0] : command;
    return cmds.indexOf(check) !== -1;
  } catch (e) {
    return true;
  }
}

function executeCommand(command) {
  if (command === 'refresh') {
    var refresh = get(STORE.REFRESH_TOKEN);
    var expiresAt = parseInt(get(STORE.EXPIRES_AT), 10);
    var now = Math.floor(Date.now() / 1000);
    var remaining = isNaN(expiresAt) ? NaN : expiresAt - now;
    var needsRefresh = isNaN(remaining) || remaining < 60;
    console.log(
      'Manual refresh. RT: ' +
        (refresh ? refresh.substring(0, 8) + '...' : 'NONE') +
        ' | Token ' +
        (isNaN(remaining)
          ? 'N/A'
          : remaining > 0
            ? 'valid (' + remaining + 's left)'
            : 'EXPIRED (' + -remaining + 's ago)') +
        ' | Refresh ' +
        (needsRefresh ? 'NEEDED' : 'not needed')
    );
    if (needsRefresh && refresh) {
      refreshToken(function (ok) {
        if (ok) {
          fetchCommandAccessibility();
          fetchCarStatus();
        } else {
          send({ STATUS_MSG: 'Re-login needed' });
        }
      });
    } else {
      fetchCommandAccessibility();
      fetchCarStatus();
    }
    return;
  }

  var vin = get(STORE.VIN);
  if (!vin) {
    sendResult('No VIN set', false);
    return;
  }
  if (!get(STORE.ACCESS_TOKEN)) {
    sendResult('Not logged in', false);
    return;
  }
  if (!get(STORE.VCC_API_KEY)) {
    sendResult('No API key', false);
    return;
  }
  if (!isCommandAvailable(command)) {
    sendResult('Not supported', false);
    return;
  }

  if (tokenExpired()) {
    refreshToken(function (ok) {
      if (ok) callApi(command, false);
      else sendResult('Re-login needed', false);
    });
  } else {
    callApi(command, false);
  }
}

function callApi(command, isRetry) {
  // Parse "path:param" format for commands with body
  var apiPath = command;
  var body = '{}';
  var colonIdx = command.indexOf(':');
  if (colonIdx !== -1) {
    apiPath = command.substring(0, colonIdx);
    var param = command.substring(colonIdx + 1);
    if (COMMANDS[apiPath] && COMMANDS[apiPath].body) {
      body = COMMANDS[apiPath].body(param);
    }
  }

  var url = VOLVO_API + '/vehicles/' + get(STORE.VIN) + '/commands/' + apiPath;
  console.log('API: POST ' + url + ' body: ' + body);

  var req = new XMLHttpRequest();
  req.open('POST', url);
  req.setRequestHeader('Content-Type', 'application/json');
  req.setRequestHeader('Authorization', 'Bearer ' + get(STORE.ACCESS_TOKEN));
  req.setRequestHeader('vcc-api-key', get(STORE.VCC_API_KEY));
  req.setRequestHeader('Accept', 'application/json');
  req.onload = function () {
    console.log('API ' + req.status + ': ' + req.responseText);
    if (req.status >= 200 && req.status < 300) {
      var msg = (COMMANDS[apiPath] && COMMANDS[apiPath].success) || 'Done';
      sendResult(msg, true);
      fetchCarStatus();
    } else if (req.status === 401 && !isRetry) {
      refreshToken(function (ok) {
        if (ok) callApi(command, true);
        else sendResult('Re-login needed', false);
      });
    } else if (req.status === 404) {
      sendResult('Not supported', false);
    } else if (req.status === 409) {
      sendResult('Already done', false);
    } else if (req.status === 422) {
      sendResult('Car busy, try later', false);
    } else if (req.status === 403) {
      sendResult('Not authorized', false);
    } else if (req.status >= 500) {
      sendResult('Volvo server error', false);
    } else {
      sendResult('Error: ' + req.status, false);
    }
  };
  req.onerror = function () {
    sendResult('Network error', false);
  };
  req.send(body);
}

// Find Car
//
// FIND_CAR wire format: "distance|bearing|note", e.g. "350 m|45|seen 5 min ago"
// (bearing -1 = no direction), or "!text" for a status/error message.
// Both positions stay on the phone; nothing is sent to the Lambda.

var FIND_MIN_INTERVAL_MS = 2000;
var FIND_CLOSE_M = 30;
var FIND_MSG_DENIED = 'Check location: phone + Pebble app';
var FIND_MSG_LOCATION_OFF = 'Turn on phone location';
var findSession = null;

function toRad(d) {
  return (d * Math.PI) / 180;
}

function haversineMeters(a, b) {
  var dLat = toRad(b.lat - a.lat);
  var dLon = toRad(b.lon - a.lon);
  var h =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
  return 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(h)));
}

function bearingDegrees(a, b) {
  var y = Math.sin(toRad(b.lon - a.lon)) * Math.cos(toRad(b.lat));
  var x =
    Math.cos(toRad(a.lat)) * Math.sin(toRad(b.lat)) -
    Math.sin(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.cos(toRad(b.lon - a.lon));
  return Math.round(((Math.atan2(y, x) * 180) / Math.PI + 360) % 360);
}

function formatDistance(m) {
  if (m < 1000) return Math.round(m / 10) * 10 + ' m';
  if (m < 10000) return (m / 1000).toFixed(1) + ' km';
  return Math.round(m / 1000) + ' km';
}

function formatAge(ts) {
  if (!ts) return '';
  var min = Math.floor((Date.now() - ts) / 60000);
  if (isNaN(min)) return '';
  if (min < 1) return 'seen just now';
  if (min < 60) return 'seen ' + min + ' min ago';
  if (min < 48 * 60) return 'seen ' + Math.floor(min / 60) + ' h ago';
  return 'seen ' + Math.floor(min / 1440) + ' d ago';
}

function parseCarLocation(resp) {
  var data = resp && (resp.data || resp);
  var c = data && data.geometry && data.geometry.coordinates;
  if (!c || typeof c[0] !== 'number' || typeof c[1] !== 'number') return null;
  var props = data.properties || {};
  console.log('Car location properties: ' + JSON.stringify(props));
  var ts = Date.parse(props.timestamp || props.updatedAt || '');
  return { lon: c[0], lat: c[1], ts: isNaN(ts) ? 0 : ts };
}

function findSend(session, msg) {
  if (findSession !== session || msg === session.lastMsg) return;
  var wait = session.lastSentAt + FIND_MIN_INTERVAL_MS - Date.now();
  if (wait > 0) {
    session.pending = msg;
    if (!session.timer)
      session.timer = setTimeout(function () {
        session.timer = null;
        findSend(session, session.pending);
      }, wait);
    return;
  }
  session.lastMsg = msg;
  session.lastSentAt = Date.now();
  send({ FIND_CAR: msg });
}

function findUpdate(session) {
  if (session.error) return findSend(session, '!' + session.error);
  if (!session.car) return findSend(session, '!Locating car...');
  if (!session.phone) return findSend(session, '!Waiting for GPS...');

  var dist = haversineMeters(session.phone, session.car);
  var age = formatAge(session.car.ts);
  if (dist <= Math.max(FIND_CLOSE_M, session.phone.accuracy || 0)) {
    return findSend(session, formatDistance(dist) + "|-1|You're close");
  }
  var bearing = bearingDegrees(session.phone, session.car);
  findSend(session, formatDistance(dist) + '|' + bearing + '|' + age);
}

function findCarStart() {
  findCarStop();
  var session = {
    car: null,
    phone: null,
    error: '',
    watchId: null,
    timer: null,
    lastMsg: '',
    lastSentAt: 0,
    pending: ''
  };
  findSession = session;

  var vin = get(STORE.VIN);
  if (!vin || !get(STORE.ACCESS_TOKEN)) {
    session.error = vin ? 'Log in first' : 'Set VIN first';
    return findUpdate(session);
  }
  findUpdate(session);

  var fetchCar = function () {
    volvoGet(LOCATION_API + '/vehicles/' + vin + '/location', function (resp, status) {
      if (findSession !== session) return;
      session.car = resp && parseCarLocation(resp);
      if (!session.car) {
        // 403: token from a login before location:read was added to the Volvo app
        if (status === 403) session.error = 'Log in again to enable';
        else if (status === 401) session.error = 'Re-login needed';
        else session.error = 'Car location unavailable';
      }
      findUpdate(session);
    });
  };
  if (tokenExpired()) {
    refreshToken(function (ok) {
      if (findSession !== session) return;
      if (ok) fetchCar();
      else {
        session.error = 'Re-login needed';
        findUpdate(session);
      }
    });
  } else {
    fetchCar();
  }

  if (!navigator.geolocation) {
    session.error = 'No location on this phone';
    return findUpdate(session);
  }
  session.watchId = navigator.geolocation.watchPosition(
    function (pos) {
      if (findSession !== session) return;
      if (session.error === FIND_MSG_LOCATION_OFF) session.error = '';
      session.phone = {
        lat: pos.coords.latitude,
        lon: pos.coords.longitude,
        accuracy: pos.coords.accuracy
      };
      findUpdate(session);
    },
    function (err) {
      if (findSession !== session) return;
      console.log('Geolocation error ' + err.code + ': ' + err.message);
      // 1 = permission denied (Android → Pebble app, or Pebble app → ReVolver)
      // 2 = position unavailable (usually phone location turned off); keep watching
      // 3 = timeout; keep watching, the screen stays on "Waiting for GPS..."
      if (err.code === 1 || err.code === 2) {
        session.error = err.code === 1 ? FIND_MSG_DENIED : FIND_MSG_LOCATION_OFF;
        findUpdate(session);
      }
    },
    { enableHighAccuracy: true, maximumAge: 5000, timeout: 30000 }
  );
}

function findCarStop() {
  if (!findSession) return;
  if (findSession.watchId !== null) navigator.geolocation.clearWatch(findSession.watchId);
  if (findSession.timer) clearTimeout(findSession.timer);
  findSession = null;
}

// Event Handlers

Pebble.addEventListener('ready', function () {
  console.log('ReVolver ready (env: ' + env.ENV + ')');

  // Send cached data immediately (no delay)
  var vin = get(STORE.VIN);
  if (vin) send({ VIN: vin });
  var info = get(STORE.CAR_INFO);
  if (info) send({ CAR_INFO: info });

  if (tokenExpired()) {
    var refresh = get(STORE.REFRESH_TOKEN);
    var expiresAt = parseInt(get(STORE.EXPIRES_AT), 10);
    var now = Math.floor(Date.now() / 1000);
    console.log(
      'Token expired on launch. RT: ' + (refresh ? refresh.substring(0, 8) + '...' : 'NONE')
    );
    console.log(
      'Expires: ' +
        (isNaN(expiresAt) ? 'N/A' : new Date(expiresAt * 1000).toISOString()) +
        ' (remaining: ' +
        (expiresAt - now) +
        's)'
    );
    send({ STATUS_MSG: 'Refreshing...' });
    refreshToken(function () {
      sendStatus();
    });
  } else {
    sendStatus();
  }

  // A browser login may have finished while the app was closed
  if (storedPairing()) pollPairing();
});

Pebble.addEventListener('appmessage', function (e) {
  var cmd = e.payload.COMMAND || e.payload[String(keys.COMMAND)];
  if (cmd) {
    console.log('Command: ' + cmd);
    if (cmd === 'find:start') findCarStart();
    else if (cmd === 'find:stop') findCarStop();
    else executeCommand(cmd);
  }
});

Pebble.addEventListener('showConfiguration', function () {
  // Without a pairing the auth page falls back to the in-webview login.
  startPairing(function (p) {
    clay = buildClay(p ? env.AUTH_URL + '?pair=' + encodeURIComponent(p.code) : env.AUTH_URL);
    Pebble.openURL(clay.generateUrl());
    if (p) pollPairing();
  });
});

// Clay may key settings by name or by numeric message key, and wrap values in {value}.
function settingValue(dict, name) {
  var v = dict[name] !== undefined ? dict[name] : dict[String(keys[name])];
  return v !== null && typeof v === 'object' ? v.value : v;
}

Pebble.addEventListener('webviewclosed', function (e) {
  if (!e || !e.response) return;
  console.log('webviewclosed payload: ' + decodeURIComponent(e.response).substring(0, 200));

  // Auth response (from ReVolverAuth)
  try {
    var data = JSON.parse(decodeURIComponent(e.response));
    if (data && !Array.isArray(data) && data.ACCESS_TOKEN) {
      saveAuth(data);
      return;
    }
  } catch (ex) {}

  // Clay settings response
  try {
    var dict = clay.getSettings(e.response);
    var vin = dict.VIN || dict[String(keys.VIN)];
    if (vin) {
      if (typeof vin === 'object') vin = vin.value;
      if (vin) {
        var oldVin = get(STORE.VIN);
        set(STORE.VIN, String(vin));
        // Clear cached car data if VIN changed
        if (oldVin && oldVin !== String(vin)) {
          clear(STORE.CAR_INFO);
          clear(STORE.AVAILABLE_COMMANDS);
          clear(STORE.ENERGY_CAPABLE);
        }
      }
    }
    var vibrate = dict.VIBRATE !== undefined ? dict.VIBRATE : dict[String(keys.VIBRATE)];
    if (vibrate !== undefined) {
      var val = typeof vibrate === 'object' ? vibrate.value : vibrate;
      send({ VIBRATE: val ? 1 : 0 });
    }
    var quick = settingValue(dict, 'QUICK_ACTION');
    var quickExit = settingValue(dict, 'QUICK_EXIT');
    if (quick !== undefined || quickExit !== undefined) {
      // "" can't be sent as an AppMessage string reliably; the watch treats "none" as off.
      send({ QUICK_ACTION: quick ? String(quick) : 'none', QUICK_EXIT: quickExit ? 1 : 0 });
    }
    sendStatus();
  } catch (ex) {
    console.log('Settings parse error: ' + ex);
  }
});
